import logging
import os
from base64 import b64decode

from taf.internal.gnb.oam.coam.vdu.client.trs.v1 import (
    ApiClient,
    AsyncOperationsApi,
    CertificateFile,
    CertMgtApi,
    Configuration,
    DiagnosticApi,
    PmtuDiscoverySetup,
    PreSharedKey,
    PutTraceCommonConfiguration,
    SecurityApi,
    TraceConfigurationApi,
    ApiException
)
from taf.internal.gnb.oam.coam.vdu.client.trs.v1.models import CmpSettings

from taf.gnb.oam.coam.vdu.services.trs.http_client_v1 import TRSv1HttpClient
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh(api_exception=ApiException)
class TRSv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.cert_mgt_api = CertMgtApi(api_client)
        self.async_operations_api = AsyncOperationsApi(api_client)
        self.trace_configuration_api = TraceConfigurationApi(api_client)
        self.diagnostic_api = DiagnosticApi(api_client)
        self.security_api = SecurityApi(api_client)
        self.local_client = TRSv1HttpClient(base_url=con_details.base_url,
                                            connection_alias=con_details.alias)

    def generate_vdu_csr(self, timeout=30):
        return self.cert_mgt_api.operator_csr_post(_request_timeout=timeout)

    def get_trs_api_operation_status(self, operation_id, timeout=30):
        return self.async_operations_api.operations_id_get(id=operation_id, _request_timeout=timeout)

    def get_vdu_csr(self, timeout=30):
        csr_file = self.cert_mgt_api.operator_csr_get(_request_timeout=timeout)
        logging.info(f"the csr file is stored in {csr_file}.")

        with open(csr_file, 'rb') as f:
            csr_content = f.read()
            logging.info(f"the csr file content is {csr_content}.")

        os.remove(csr_file)
        return b64decode(csr_content).decode('utf-8')

    def install_vdu_certificates(self, cert_file_path, cert_type='EE', cert_file_encoding='pem'):
        with open(cert_file_path, 'rb') as f:
            cert_file_content = f.read().decode('utf-8')
        cert_file_name = os.path.basename(cert_file_path).split('.')[0]
        cert_file = CertificateFile(certificate_file=cert_file_content,
                                    file_encoding=cert_file_encoding,
                                    certificate_type=cert_type,
                                    file_name=cert_file_name)
        return self.cert_mgt_api.operator_certificates_post(certificate_file=cert_file,
                                                            _request_timeout=30)

    def get_vdu_certificates(self, timeout=30):
        return self.cert_mgt_api.operator_certificates_get(_request_timeout=timeout)

    def restore_default_certificates(self, timeout=30):
        return self.cert_mgt_api.operator_certificates_delete(_request_timeout=timeout)

    def delete_certificates_by_id(self, id, timeout=30):
        return self.local_client.delete_certificates_by_id(certificate_id=id, timeout=timeout)

    def update_uplane_configuration(self, uplane_ip_addr, uplane_port, dscp, timeout=30):
        put_trace_common_configuration = PutTraceCommonConfiguration(uplane_ip_address=uplane_ip_addr,
                                                                     uplane_port=uplane_port,
                                                                     dscp=dscp,
                                                                     trace_type="UPlane")
        return self.trace_configuration_api.update_trace_common_configuration(put_trace_common_configuration,
                                                                              _request_timeout=timeout)

    def update_vdu_cmp_server_settings(self, ref_number, psk_key, timeout=30):
        cmp_settings = CmpSettings(ref_number=ref_number, psk_key=psk_key)
        return self.cert_mgt_api.cmp_server_settings_put(cmp_settings=cmp_settings,
                                                         _request_timeout=timeout)

    def get_vdu_crl_information(self, timeout=30):
        return self.cert_mgt_api.crl_get(_request_timeout=timeout)

    def initialize_certificate(self, timeout=30):
        return self.cert_mgt_api.cmp_certificate_initialization_post(_request_timeout=timeout)

    def update_cmp_server_key(self, timeout=30):
        return self.cert_mgt_api.cmp_server_key_post(_request_timeout=timeout)

    def update_CRL_info(self, timeout=30):
        return self.cert_mgt_api.crl_post(_request_timeout=timeout)

    def update_cplane_configuration(self, dscp, timeout=30):
        put_trace_common_configuration = PutTraceCommonConfiguration(dscp=dscp,
                                                                     trace_type="CPlane")
        return self.trace_configuration_api.update_trace_common_configuration(put_trace_common_configuration,
                                                                              _request_timeout=timeout)

    def start_ip_connectivity_test(self, destination_ip, payload_size, dscp, source_interface_name, source_ip,
                                   timeout=30):
        result = self.local_client.start_ip_connectivity_test(destination_ip=destination_ip,
                                                              payload_size=payload_size,
                                                              dscp=dscp,
                                                              source_interface_name=source_interface_name,
                                                              source_ip=source_ip,
                                                              timeout=timeout)
        return result

    def get_ip_connectivity_test_result(self, operation_id, timeout=30):
        return self.local_client.get_ip_connectivity_test_result(operation_id=operation_id, timeout=timeout)

    def start_pmtu_discovery(self, name, source_ip, destination_ip, dscp, timeout=30):
        pmtu_discovery_setup = PmtuDiscoverySetup(name=name,
                                                  source_ip=source_ip,
                                                  destination_ip=destination_ip,
                                                  dscp=dscp)
        return self.diagnostic_api.start_pmtu_discovery(pmtu_discovery_setup=pmtu_discovery_setup,
                                                        _request_timeout=timeout)

    def get_pmtu_discovery_status(self, operation_id, timeout=30):
        return self.diagnostic_api.get_pmtu_discovery_status(id=operation_id, _request_timeout=timeout)

    def update_vdu_psk_configuration(self, password, timeout=30):
        pre_shared_key = PreSharedKey(password=password)
        return self.security_api.security_presharedkey_post(pre_shared_key=pre_shared_key, _request_timeout=timeout)

    def get_ip_security_associations(self, policy_id, tnl_pod_hostname, timeout=30):
        return self.security_api.security_ike_policies_get(policy_id=policy_id,
                                                           tnl_host_name=tnl_pod_hostname,
                                                           _request_timeout=timeout)

    def get_external_interfaces_of_pmtu_discovery(self, timeout=30):
        return self.local_client.get_external_interfaces_of_pmtu_discovery(timeout=timeout)
